import { defineComponent } from 'vue';
import { userModel } from '../../..';
import { PrizeLeagueManager } from '../../../services/prize-league/prize-league-manager';
import BottomPanel from '../bottom-panel/bottom-panel.vue';
import MenuBar from '../menu-bar/menu-bar.vue';
import { getPrizeLeagueManager, truncateUsername } from '../prize-league-utils';
import { inversifyContainer } from '../../../inversify/container';

export default defineComponent({
    name: 'Leaderboard',
    components: {
        BottomPanel,
        MenuBar
    },
    props: {
        visible: {
            type: Boolean,
            default: true
        },
        tournamentId: {
            type: String,
            default: ''
        }
    },
    data() {
        return {
            username: truncateUsername(userModel.username)
        };
    },
    computed: {
        prizeLeagueManager(): PrizeLeagueManager {
            return getPrizeLeagueManager();
        },
        leaderboard() {
            const viewed = this.currentlyViewedTournament;
            if (!viewed || viewed.tournamentId !== this.tournamentId) {
                return [];
            }
            // Don't show leaderboard for upcoming tournaments that haven't started
            if (viewed.tournamentStatus === 'Upcoming') {
                return [];
            }
            return this.prizeLeagueManager.leaderboard.value;
        },
        tournamentList() {
            return this.prizeLeagueManager.tournamentList.value;
        },
        activeTournament() {
            return this.prizeLeagueManager.activeTournament.value;
        },
        currentlyViewedTournament() {
            return this.prizeLeagueManager.currentlyViewedTournament.value;
        },
        translations() {
            return inversifyContainer.strings.prizeLeague;
        },
        isUpcoming(): boolean {
            const viewed = this.currentlyViewedTournament;
            return !!viewed && viewed.tournamentStatus === 'Upcoming';
        },
        hasNotOptedIn(): boolean {
            return !this.currentlyViewedTournament?.hasOptedIn;
        },
        isActiveTournament(): boolean {
            return this.currentlyViewedTournament?.tournamentId === this.activeTournament?.tournamentId;
        },
        hasNotSpunYet(): boolean {
            const viewed = this.currentlyViewedTournament;
            if (!viewed || viewed.tournamentStatus !== 'Active') {
                return false;
            }
            return this.activeTournament?.tournamentId === this.tournamentId && 
                   this.activeTournament?.spinsUsed === 0;
        },
        shouldShowBottomPanel(): boolean {
            // Show if not active tournament OR if active but not opted in
            return !this.isActiveTournament || !this.currentlyViewedTournament?.hasOptedIn;
        }
    },
    emits: ['change-panel']
});